<template><section class="overview-page">
  <div class="page-heading"><div class="overview-title"><h1>运行总览</h1><span class="date-label"><Calendar :size="19"/>{{date}}</span></div><span class="overview-live"><i :class="{connected:camera.status.serviceState==='ready'}"/>{{camera.status.serviceState==='ready'?'数据实时更新':'等待设备连接'}}</span></div>
  <p v-if="error" class="error-banner">{{error}}</p>
  <div class="metric-grid"><div v-for="(m,i) in metrics" :key="m.label" class="panel metric-card"><span class="metric-icon" :class="{amber:i===2}"><component :is="m.icon" :size="34" :stroke-width="1.8"/></span><div class="metric-value"><span>{{m.label}}</span><strong>{{m.value}}<small v-if="i===0">/2</small></strong></div><CircleCheck v-if="i===0&&m.value===2" class="metric-ok" :size="23" fill="#00ad22" color="white"/><span v-else-if="i===0" class="metric-caption">待接入</span></div></div>
  <div class="overview-upper"><div class="panel overview-map"><div class="panel-heading"><h3>校园总览</h3><RouterLink to="/workbench" class="btn primary"><Play :size="17" fill="currentColor"/>进入实时监控</RouterLink></div><div class="campus-overview"><CampusMap/></div></div>
    <div class="overview-side"><div class="panel pending-panel"><div class="panel-heading"><h3>待办事件 <span class="pending-number">（{{data?.pendingEvents??0}}）</span></h3><RouterLink to="/events" class="subtle-link">查看全部 <ChevronRight :size="15"/></RouterLink></div><div v-if="pending" class="pending-card"><div class="pending-summary"><strong><span class="badge warning">{{pending.trackId}}</span>目标检测</strong><time><Calendar :size="18"/>{{fullTime(pending.startedAt)}}</time></div><RouterLink :to="'/events?id='+pending.id" class="btn primary">{{auth.can('review')?'立即复核':'查看事件'}}</RouterLink></div><div v-else class="pending-empty"><CircleCheck :size="31" :stroke-width="1.5"/><div><strong>当前没有待复核事件</strong><p>新事件将自动出现在这里</p></div></div></div>
      <div class="panel health-panel"><div class="panel-heading"><h3>系统健康</h3><span class="muted">实时状态</span></div><div class="health-list"><div v-for="h in health" :key="h.name"><span><component :is="h.icon" :size="22"/>{{h.name}}</span><span class="health-state" :class="{healthy:h.ok}"><i/>{{h.text}}</span></div></div></div>
    </div>
  </div>
  <div class="overview-lower"><div class="panel recent-panel"><div class="panel-heading"><h3>最近事件</h3><RouterLink to="/events" class="subtle-link">全部事件 <ChevronRight :size="15"/></RouterLink></div><div class="table-wrap"><table><colgroup><col style="width:9.5%"/><col style="width:15%"/><col style="width:22%"/><col style="width:24%"/><col style="width:14%"/><col style="width:15.5%"/></colgroup><thead><tr><th>序号</th><th>目标编号</th><th>事件类型</th><th>发生时间</th><th>处理状态</th><th>操作</th></tr></thead><tbody><tr v-for="(e,index) in (data?.recentEvents||[]).slice(0,3)" :key="e.id"><td>{{index+1}}</td><td><span class="badge" :class="e.status==='pending'?'warning':'blue'">{{e.trackId}}</span></td><td>目标检测</td><td class="event-time">{{fullTime(e.startedAt)}}</td><td><span class="badge" :class="e.status==='pending'?'warning':'success'">{{e.status==='pending'?'待复核':'已复核'}}</span></td><td><RouterLink :to="'/events?id='+e.id" class="event-link">{{e.status==='pending'&&auth.can('review')?'立即复核':'查看'}}</RouterLink></td></tr><tr v-if="!data?.recentEvents?.length"><td colspan="6" class="recent-empty"><ScanLine :size="24"/><span>暂无事件记录</span></td></tr></tbody></table></div></div>
    <div class="panel trend-panel"><div class="panel-heading"><h3>事件按小时统计</h3></div><span class="chart-unit">事件数</span><div class="chart-body"><div class="chart-y"><span v-for="value in chartTicks" :key="value">{{value}}</span></div><div class="bar-chart"><div v-for="(count,i) in displayHours" :key="i" class="bar-column" :title="i+'时：'+count+'件'"><div :style="{height:(count?Math.max(2,count/chartMax*100):0)+'%'}"/><small v-if="displayHours.length<=12||i%2===0">{{String(i).padStart(2,'0')}}:00</small></div></div></div></div>
  </div>
</section></template>
<script setup lang="ts">
import{computed,ref,onMounted,onUnmounted}from'vue';import{ChevronRight,Calendar,Play,ScanLine,TriangleAlert,CircleCheck,Video,Cpu,LocateFixed,Database}from'lucide-vue-next';import{http}from'@/api/http';import{useCameraStore}from'@/stores/camera';import{dateTime}from'@/lib/product-format';import CampusMap from'@/components/CampusMap.vue';import{useAuthStore}from'@/stores/auth';import ServerGlyph from'@/components/ServerGlyph.vue';
const camera=useCameraStore(),auth=useAuthStore();const data=ref<any>(null),error=ref(''),fresh=ref(false),now=ref(Date.now());const date=computed(()=>new Intl.DateTimeFormat('zh-CN',{year:'numeric',month:'long',day:'numeric'}).format(new Date(now.value)));
const metrics=computed(()=>[{label:'在线设备',value:data.value?.onlineDevices??0,icon:ServerGlyph},{label:'监测中目标',value:data.value?.activeTargets??0,icon:LocateFixed},{label:'待复核事件',value:data.value?.pendingEvents??0,icon:TriangleAlert},{label:'今日事件',value:data.value?.todayEvents??0,icon:Calendar}]);const pending=computed(()=>data.value?.pendingEvent);
const health=computed(()=>[{name:'视频接入',icon:Video,ok:Object.values(camera.status.cameras).every(c=>c.state==='streaming'),text:Object.values(camera.status.cameras).every(c=>c.state==='streaming')?'已连接':Object.values(camera.status.cameras).some(c=>c.state==='streaming')?'部分连接':'未连接'},{name:'推理服务',icon:Cpu,ok:camera.status.engineState==='ready',text:camera.status.engineState==='ready'?'正常':'未就绪'},{name:'空间标定',icon:LocateFixed,ok:camera.status.serviceState==='ready'&&!['uncalibrated','error'].includes(camera.status.spatial.state),text:camera.status.serviceState==='ready'&&!['uncalibrated','error'].includes(camera.status.spatial.state)?'已配置':'待配置'},{name:'存储服务',icon:Database,ok:fresh.value,text:fresh.value?'正常':data.value?'状态待确认':'连接中'}]);
const hours=computed(()=>Array.from({length:24},(_,i)=>{const h=data.value?.hourly?.[i];return typeof h==='number'?h:Number(h?.count||0)}));const maxCount=computed(()=>Math.max(2,...hours.value));const displayHours=computed(()=>{const lastActiveHour=hours.value.reduce((last,count,hour)=>count>0?hour:last,-1);const end=Math.min(24,Math.max(12,new Date(now.value).getHours()+2,lastActiveHour+1));return hours.value.slice(0,end)});const chartStep=computed(()=>Math.max(1,Math.ceil(maxCount.value/6)));const chartMax=computed(()=>chartStep.value*6);const chartTicks=computed(()=>Array.from({length:7},(_,i)=>(6-i)*chartStep.value));const fullTime=(time:number)=>dateTime(time).replaceAll('/','-');let stopped=false,timer:ReturnType<typeof setTimeout>,clock:ReturnType<typeof setInterval>;
async function refresh(){try{data.value=(await http.get('/overview')).data;fresh.value=true;error.value=''}catch(e){fresh.value=false;error.value='数据暂未更新：'+(e as Error).message}if(!stopped)timer=setTimeout(refresh,5000)}onMounted(()=>{clock=setInterval(()=>now.value=Date.now(),1000);void refresh()});onUnmounted(()=>{stopped=true;clearTimeout(timer);clearInterval(clock)});
</script>
